# Волна 144: составные задачи (пачки аудита 001 и 007), разбитые на независимые подзадачи.
exec(open("/audit/specs/_hlp.py", encoding="utf-8").read())
def Q(q, key, d, yn=False): return P(q, key, list(d), yn)
def YN(q, key, why): return P(q, key, [("нет" if key == "да" else "да", why)], True)
NUM = "пачка из нескольких независимых заданий в одной задаче с выбором ответа; каждое задание — отдельная задача"

SK = r"Сократите дробь $%s$, разделив числитель и знаменатель на их НОД."
T("G6_TB_21–23_187", NUM + "; сокращение дробей, открытые ответы заменены выбором из вариантов", [
 Q(SK % r"\dfrac{28}{70}", r"$\dfrac{2}{5}$", [(r"$\dfrac{4}{10}$", r"Ученик разделил числитель и знаменатель на $7$, а не на НОД $14$: дробь не сокращена до конца."), (r"$\dfrac{14}{35}$", r"Ученик разделил числитель и знаменатель на $2$, а не на НОД $14$."), (r"$\dfrac{28}{35}$", r"Ученик разделил на $2$ только знаменатель, а числитель оставил без изменения.")]),
 Q(SK % r"\dfrac{102}{180}", r"$\dfrac{17}{30}$", [(r"$\dfrac{51}{90}$", r"Ученик разделил числитель и знаменатель на $2$, а не на НОД $6$."), (r"$\dfrac{34}{60}$", r"Ученик разделил числитель и знаменатель на $3$, а не на НОД $6$."), (r"$\dfrac{17}{180}$", r"Ученик разделил на НОД $6$ только числитель, а знаменатель оставил без изменения.")]),
 Q(SK % r"\dfrac{15}{55}", r"$\dfrac{3}{11}$", [(r"$\dfrac{3}{55}$", r"Ученик разделил на НОД $5$ только числитель, а знаменатель оставил без изменения."), (r"$\dfrac{15}{11}$", r"Ученик разделил на НОД $5$ только знаменатель, а числитель оставил без изменения."), (r"$\dfrac{5}{11}$", r"Ученик разделил числитель на $3$, а знаменатель на $5$: на разные числа сокращать нельзя.")]),
])
T("G5_TB_5_151.2", NUM, [
 Q(r"Какое натуральное число лежит между $2089$ и $2091$?", r"$2090$", [(r"$2089$", r"Ученик взял левую границу промежутка, а она не лежит между числами."), (r"$2091$", r"Ученик взял правую границу промежутка, а она не лежит между числами."), (r"$2$", r"Ученик нашёл разность $2091-2089=2$ вместо числа между ними.")]),
 YN(r"Есть ли натуральное число между $6077$ и $6078$?", "нет", r"Ученик указал число $6077{,}5$, но оно не натуральное; между соседними натуральными числами других натуральных нет."),
])
SQ = r"Найдите значение $\sqrt{%d}$."
T("G8_TB_12_297.3", NUM + "; корни из таблицы квадратов", [
 Q(SQ % 576, r"$24$", [(r"$26$", r"Ученик перепутал число $576$ с $676=26^{2}$."), (r"$288$", r"Ученик разделил число на $2$ вместо извлечения квадратного корня."), (r"$42$", r"Ученик переставил цифры ответа.")]),
 Q(SQ % 1764, r"$42$", [(r"$48$", r"Ученик решил, что подходит любое число, оканчивающееся на $8$ (так как $8^{2}$ оканчивается на $4$): $48^{2}=2304$."), (r"$882$", r"Ученик разделил число на $2$ вместо извлечения квадратного корня."), (r"$24$", r"Ученик переставил цифры ответа.")]),
 Q(SQ % 7396, r"$86$", [(r"$84$", r"Ученик перепутал число $7396$ с $7056=84^{2}$."), (r"$3698$", r"Ученик разделил число на $2$ вместо извлечения квадратного корня."), (r"$68$", r"Ученик переставил цифры ответа.")]),
])
